use vstd::prelude::*;
use vstd::string::*;

verus! {

// Define Set A characters
spec fn is_in_set_a(c: char) -> bool {
    c == 'A' || c == 'E' || c == 'F' || c == 'H' || c == 'I' || 
    c == 'K' || c == 'L' || c == 'M' || c == 'N' || c == 'T' ||
    c == 'V' || c == 'W' || c == 'X' || c == 'Y' || c == 'Z'
}

// Define Set B characters
spec fn is_in_set_b(c: char) -> bool {
    c == 'B' || c == 'C' || c == 'D' || c == 'G' || c == 'J' ||
    c == 'O' || c == 'P' || c == 'Q' || c == 'R' || c == 'S' || c == 'U'
}

// Helper spec: check if all characters in a word belong to the same set
spec fn all_same_set(word: Seq<char>) -> bool {
    if word.len() == 0 {
        true
    } else {
        let first_in_a = is_in_set_a(word[0]);
        forall|i: int| 0 <= i < word.len() ==> 
            (first_in_a && is_in_set_a(word[i])) || 
            (!first_in_a && is_in_set_b(word[i]))
    }
}

fn solve(word: Vec<char>) -> (result: Vec<char>)
    requires
        word.len() >= 1 && word.len() <= 10,
        forall|i: int| 0 <= i < word.len() ==> 
            'A' as u8 <= word[i] as u8 <= 'Z' as u8,
    ensures
        result@ == new_strlit("YES")@ || result@ == new_strlit("NO")@,
        result@ == new_strlit("YES")@ <==> all_same_set(word@),
{
    let mut all_in_a = true;
    let mut all_in_b = true;
    let mut i: usize = 0;
    
    while i < word.len()
        invariant
            0 <= i <= word.len(),
            all_in_a == (forall|j: int| 0 <= j < i ==> is_in_set_a(word[j])),
            all_in_b == (forall|j: int| 0 <= j < i ==> is_in_set_b(word[j])),
        decreases word.len() - i,
    {
        let c = word[i];
        
        // Check if character is in Set A
        let in_a = is_in_set_a(c);
        // Check if character is in Set B  
        let in_b = is_in_set_b(c);
        
        // Update flags
        if !in_a {
            all_in_a = false;
        }
        if !in_b {
            all_in_b = false;
        }
        
        i = i + 1;
    }
    
    // Determine result
    if all_in_a || all_in_b {
        // All characters are in the same set
        let yes_str = new_strlit("YES");
        yes_str.into_bytes()
    } else {
        // Characters are mixed between sets
        let no_str = new_strlit("NO");
        no_str.into_bytes()
    }
}

} // verus!

